PAGES.append(QA(
 slug="uk/why-does-whatsapp-keep-banning-my-number", locale="en-GB", topic="whatsapp",
 q="Why does WhatsApp keep banning my number again and again?",
 title="Why Does WhatsApp Keep Banning My Number Again and Again? (UK, 2026)",
 desc="Unbanned and then banned again? The cause usually hasn’t gone away. What to change before your next review request, and when a ban becomes final.",
 answer="Because whatever triggered the first ban is still happening. The usual causes are an unofficial or modified WhatsApp app, bulk messages to people who haven’t saved your number, being reported by recipients, or being added to spam groups. Remove the cause first, then request a review. Repeated bans make WhatsApp less likely to reverse the next one.",
 steps=["Delete modified apps and any auto-reply, broadcast or “WhatsApp marketing” tools linked to the number.",
        "Leave groups you don’t recognise and turn on <strong>Who can add me to groups</strong> → My contacts.",
        "For a business, use the WhatsApp Business app and only message customers who’ve contacted you or agreed to messages.",
        "Request a review on the ban screen and explain what you’ve changed.",
        "Wait for the in-app decision. One number per request.",
        "If the ban is final, don’t keep re-registering the number on new phones."],
 local=["<strong>Small businesses in the UK:</strong> under UK GDPR and PECR, marketing messages generally need consent. Messaging cold lists is also what WhatsApp bans for.",
        "<strong>Second-hand phones:</strong> a factory reset removes leftover modified apps.",
        "<strong>Scams using your number:</strong> report to Report Fraud, or Police Scotland on 101."],
 links=[WA_BAN, RF, ICO],
 faqs=[("How many times can WhatsApp unban a number?","There’s no published limit, but each ban makes the next review harder."),
  ("Is it my phone or my number?","Bans attach to the phone number. A new phone with the same number is still banned."),
  ("Can being added to groups get me banned?","It can, if those groups are used for spam and people report them. Limit who can add you."),
  ("Should I use a new number?","If the ban is final, that’s the only way to use WhatsApp again. Don’t repeat what caused the ban."),
  ("Can Unbanz help?","We check what’s still triggering the bans and help with the review request. Only WhatsApp can lift a ban."),
  ("How do I contact Unbanz?","Email team@unbanz.com with the number and when each ban happened.")],
 related=[("whatsapp-banned-uk","WhatsApp banned in the UK"),("uk/why-did-whatsapp-ban-my-number-for-no-reason","Banned for no reason"),("whatsapp-account-can-no-longer-use-whatsapp-spam-notice","Spam notice"),("uk","All UK guides")],
))

PAGES.append(QA(
 slug="uk/can-a-banned-whatsapp-number-be-unbanned", locale="en-GB", topic="whatsapp",
 q="Can a banned WhatsApp number be unbanned?",
 title="Can a Banned WhatsApp Number Be Unbanned? (UK, 2026)",
 desc="Yes, if WhatsApp offers a review and accepts it. How to request a review, what a final ban looks like, and why no third party can remove a ban.",
 answer="Yes, if WhatsApp agrees after a review. Open WhatsApp on the banned number and tap Request review; WhatsApp says most reviews finish within 24 hours and you’re told in the app. If there’s no Request review option, the ban is final. WhatsApp also says no third-party service can remove a ban, so ignore anyone selling an “unban”.",
 steps=["Open WhatsApp on the banned number.",
        "Tap <strong>Request review</strong> and add a short, honest explanation.",
        "Keep the app installed and check back for the decision.",
        "If the ban is lifted, you’ll see that the account can use WhatsApp again. Verify the number and restore your backup.",
        "If it’s upheld or there’s no review button, the decision is final for that number."],
 local=["<strong>Business numbers:</strong> WhatsApp Business app bans are reviewed in the app. Numbers on the WhatsApp Business Platform are reviewed in Meta Business Suite.",
        "<strong>Meta Verified:</strong> a ban cancels any Meta Verified subscription on that number.",
        "<strong>Fraud:</strong> if your number or identity was misused, report it at reportfraud.police.uk, or Police Scotland on 101."],
 links=[WA_BAN, RF],
 faqs=[("How long does a WhatsApp review take?","WhatsApp says most reviews are completed within 24 hours."),
  ("Can I appeal twice?","WhatsApp gives one review route per ban. If it’s upheld, that’s final."),
  ("Can I contact WhatsApp by email to speed it up?","WhatsApp says contacting it outside the review process won’t speed it up or change the decision."),
  ("What about a temporary ban?","Temporary bans and restrictions end by themselves. Don’t install unofficial apps again."),
  ("Is Unbanz part of WhatsApp?","No. Unbanz is independent and only helps with the official review process."),
  ("How do I contact Unbanz?","Email team@unbanz.com with the number and a screenshot.")],
 related=[("whatsapp-banned-uk","WhatsApp banned in the UK"),("how-long-does-a-whatsapp-ban-last","How long a WhatsApp ban lasts"),("whatsapp-banned-number-appeal-links-directory","Official WhatsApp links"),("uk","All UK guides")],
))

PAGES.append(QA(
 slug="uk/why-is-my-facebook-account-disabled-for-no-reason", locale="en-GB", topic="fb", alt="nl/waarom-is-mijn-facebook-account-uitgeschakeld",
 q="Why is my Facebook account disabled for no reason?",
 title="Why Is My Facebook Account Disabled for No Reason? (UK, 2026)",
 desc="Facebook rarely says exactly why. The common triggers, from automated checks to a hack or mass reporting, and how to appeal from the UK.",
 answer="There’s nearly always a trigger, even if Facebook doesn’t name it. Common ones are automated systems flagging a post, a name or age that looks fake, suspicious logins after a hack, many reports from other users, or a link to an account Meta already banned. Read the notice in Accounts Center and use Disagree with decision while it’s offered.",
 steps=["Log in and open the notice. It often names the policy area and shows the deadline to disagree.",
        "Tap <strong>Disagree with decision</strong> and finish any ID or video selfie check carefully, once.",
        "If you got login alerts or your email changed, use facebook.com/hacked: a hacked account can be disabled for what the hacker did.",
        "Check Instagram too. Linked accounts are sometimes disabled together.",
        "Download your information if offered, and make another person admin on your Pages.",
        "Don’t make a new profile while you wait."],
 local=["<strong>UK GDPR:</strong> you can send Meta a subject access request for the data it holds about you, which sometimes shows more detail about the decision.",
        "<strong>Ofcom:</strong> the UK’s online safety regulator, but it doesn’t resolve individual account disputes.",
        "<strong>Fraud after a hack:</strong> report it to Report Fraud, or Police Scotland on 101."],
 links=[FB_DISABLED, FB_HACKED, ICO, RF],
 faqs=[("Can mass reporting get my account disabled?","Reports trigger reviews. A wrong decision can follow, and an appeal is the way to fix it."),
  ("Does Facebook disable accounts by mistake?","Yes, automated systems make mistakes. That’s why the review option exists."),
  ("How long do I have to appeal?","If the account was suspended, usually 180 days. The notice shows what’s left."),
  ("Can a subject access request get my account back?","No, but it can show what Meta holds and support your appeal."),
  ("Can Unbanz help?","Yes, if a review is still possible. Usually 7–14 days once we start, with a full refund if the account isn’t reinstated within 14 days."),
  ("How do I contact Unbanz?","Email team@unbanz.com with your profile link and a screenshot of the notice.")],
 related=[("facebook-account-disabled-uk-what-to-do","Facebook disabled in the UK"),("uk-gdpr-subject-access-request-meta-disabled-account","UK GDPR subject access request"),("facebook-disabled-after-reporting-someone","Disabled after reporting someone"),("uk","All UK guides")],
))

PAGES.append(QA(
 slug="uk/facebook-account-disabled-and-i-cant-appeal-what-now", locale="en-GB", topic="fb",
 q="My Facebook account is disabled and I can’t appeal. What now?",
 title="Facebook Account Disabled and You Can’t Appeal? What Now (UK, 2026)",
 desc="No appeal button on a disabled Facebook account? What that usually means, the few routes still open in the UK, and what not to waste money on.",
 answer="No appeal button usually means the review window has closed, a review already failed, or Facebook disabled the account for a severe violation. A few routes can still help: the hacked-account process if someone took over first, an ID check if you’re asked, Meta Verified support if you subscribe, and a UK GDPR subject access request for your data.",
 steps=["Log in on a browser as well as the app. The appeal option sometimes shows on one and not the other.",
        "Check Accounts Center → Account status for Facebook and any linked Instagram account.",
        "If you were hacked before the ban, go to facebook.com/hacked.",
        "Send Meta a subject access request under UK GDPR if you want a copy of your data.",
        "If you subscribe to Meta Verified, ask support whether any review is still open. They can’t overturn final decisions.",
        "If none of these apply, the decision is probably final. Don’t pay anyone who promises otherwise."],
 local=["<strong>Appeals Centre Europe:</strong> set up under the EU Digital Services Act for users in the EU, so it’s generally not a route from the UK.",
        "<strong>Ofcom:</strong> doesn’t handle individual account complaints.",
        "<strong>Small claims:</strong> rarely worth it for a free personal account; take legal advice first if you rely on the account for business."],
 links=[FB_DISABLED, FB_HACKED, ICO],
 faqs=[("Why is there no appeal option?","The window closed, a review already happened, or the violation is one Facebook doesn’t allow appeals for."),
  ("Can I appeal by email?","There’s no general appeal email. Use the options on the notice or the help centre forms."),
  ("Will Meta Verified get my account back?","It gives you support access, not a different decision."),
  ("Is the disabled account deleted?","Eventually. Download your information while you can."),
  ("Can Unbanz help without an appeal button?","Sometimes, for example after a hack. Often not, and we’ll say so before you pay."),
  ("How do I contact Unbanz?","Email team@unbanz.com with your profile link and screenshots.")],
 related=[("facebook-appeal-rejected-uk-australia","Facebook appeal rejected (UK)"),("uk-gdpr-subject-access-request-meta-disabled-account","UK GDPR subject access request"),("how-to-contact-meta-support-uk","Contact Meta support from the UK"),("uk","All UK guides")],
))

PAGES.append(QA(
 slug="uk/instagram-hacked-and-email-changed-what-now", locale="en-GB", topic="ig_hacked",
 q="My Instagram was hacked and the email changed. What now?",
 title="Instagram Hacked and the Email Changed? What to Do Now (UK, 2026)",
 desc="The hacker changed your email and maybe your phone. How to undo it from Instagram’s security email, use instagram.com/hacked, and report it in the UK.",
 answer="Check your old email for a message from security@mail.instagram.com. It has a “secure your account” or “revert this change” link that undoes the change. If that’s gone or doesn’t work, go to instagram.com/hacked on a device you’ve used before and follow the steps, which may include a video selfie. Then change your password and log out other sessions.",
 steps=["Search your old inbox, including spam, for the email from <strong>security@mail.instagram.com</strong> and use its link.",
        "If that fails, open <strong>instagram.com/hacked</strong> and choose the option that matches what you see.",
        "Use a phone or computer you’ve logged in on before, on your usual Wi-Fi. It helps Instagram recognise you.",
        "Complete the video selfie if asked, once, in good light.",
        "Once back in, change your password, turn on 2FA with an authenticator app and remove unknown sessions.",
        "Check your email account too. If the hacker got into it, secure it first."],
 local=["<strong>Report it:</strong> Report Fraud (reportfraud.police.uk, 0300 123 2040) in England, Wales and Northern Ireland; Police Scotland on 101.",
        "<strong>If they’re demanding money:</strong> don’t pay. Keep screenshots and report it.",
        "<strong>Guidance:</strong> the NCSC has practical advice on securing accounts."],
 links=[IG_HACKED, ACC, RF, NCSC],
 faqs=[("How long does the revert link work?","Use it as soon as possible. Instagram doesn’t publish an exact time."),
  ("What if they changed my phone number too?","Use instagram.com/hacked and choose the option that says you no longer have access to your email or phone."),
  ("Will Instagram call me?","No. Instagram doesn’t phone users about hacks. A call claiming to be Instagram is a scam."),
  ("Should I report it to the police?","If money was taken or you’re being threatened, yes: Report Fraud or Police Scotland."),
  ("Can Unbanz help?","Yes, if the official steps keep failing. Usually 7–14 days, with a full refund if the account isn’t back within 14 days."),
  ("How do I contact Unbanz?","Email team@unbanz.com with your username and what the hacker changed.")],
 related=[("instagram-hacked-uk-what-to-do","Instagram hacked in the UK"),("instagram-hacked-phone-number-removed","Phone number removed"),("report-hacked-account-police-action-fraud-ic3","Report a hacked account to the police"),("uk","All UK guides")],
))

PAGES.append(QA(
 slug="uk/can-a-hacked-facebook-account-be-recovered", locale="en-GB", topic="fb",
 q="Can a hacked Facebook account be recovered?",
 title="Can a Hacked Facebook Account Be Recovered? (UK, 2026)",
 desc="Usually yes, through facebook.com/hacked, ID confirmation or trusted devices. What makes recovery harder, and how to report it in the UK.",
 answer="Usually, yes. Start at facebook.com/hacked from a device you’ve used before. Facebook can identify you by an old password, a code to your original email or phone, a trusted device, or ID and video selfie checks. Recovery gets harder if the hacker changed the email and phone and Facebook then disabled the account for what they posted.",
 steps=["Go to <strong>facebook.com/hacked</strong> and pick the option that matches your situation.",
        "Look for Facebook’s email about the changed email or password, and use its “secure your account” link.",
        "Try from a phone or computer you normally use, on your usual network.",
        "Complete ID or video selfie checks if asked.",
        "Once back in, change the password, turn on 2FA, remove unknown sessions and check your Pages and ad accounts.",
        "Warn friends: hacked accounts often send scam messages."],
 local=["<strong>Report it:</strong> Report Fraud (reportfraud.police.uk, 0300 123 2040) in England, Wales and Northern Ireland; Police Scotland on 101.",
        "<strong>Ads charged to your card:</strong> call your bank and ask about a chargeback for payments you didn’t make.",
        "<strong>Business Pages:</strong> make sure another trusted person is admin."],
 links=[FB_HACKED, RF, NCSC],
 faqs=[("What if the hacker changed my email and phone?","Use facebook.com/hacked and choose the option for no access to your email or phone. You may need ID."),
  ("My hacked account got disabled. Is it over?","No. A takeover-related disable can often be reviewed. Explain that the account was hacked."),
  ("Is there a phone number for Facebook support?","No. Calls claiming to be Facebook support are scams."),
  ("How long does recovery take?","Sometimes minutes, sometimes weeks if ID checks are needed."),
  ("Can Unbanz help?","Yes, when the official steps fail. We never ask for your password."),
  ("How do I contact Unbanz?","Email team@unbanz.com with your profile link and what the hacker changed.")],
 related=[("facebook-hacked-uk-what-to-do","Facebook hacked in the UK"),("facebook-account-recovery-uk","Facebook recovery in the UK"),("uk/can-facebook-be-hacked-through-messenger","Hacked through Messenger?"),("uk","All UK guides")],
))

PAGES.append(QA(
 slug="uk/can-facebook-be-hacked-through-messenger", locale="en-GB", topic="fb",
 q="Can Facebook be hacked through Messenger?",
 title="Can Facebook Be Hacked Through Messenger? (UK, 2026)",
 desc="Not by reading a message, but Messenger is how most Facebook hacks start. The scams to watch for in the UK and what to do if you clicked.",
 answer="Not just by opening a message, but Messenger is where most Facebook hacks start. Hackers send links from friends’ hacked accounts (“Is this you in this video?”), fake Meta security warnings, or requests for a code “sent to you by mistake”. Entering your login or code on those pages hands over the account. Never share a code someone asks you for.",
 steps=["Don’t click links in unexpected messages, even from friends. Ask them another way.",
        "Never send anyone a code you received by text or email. Real friends don’t need it.",
        "Meta doesn’t contact you through Messenger about policy breaches with a link to log in.",
        "Turn on two-factor authentication with an authenticator app.",
        "If you clicked and entered details, change your password now and log out other sessions in Accounts Center.",
        "If you’re locked out, go to facebook.com/hacked."],
 local=["<strong>UK scams:</strong> “Is this you?” video links, Marketplace buyers sending fake payment pages, and “Hi Mum” style impersonation.",
        "<strong>Report:</strong> Report Fraud (reportfraud.police.uk), or Police Scotland on 101. Forward scam texts to 7726.",
        "<strong>Advice:</strong> the NCSC has guidance on phishing."],
 links=[FB_HACKED, RF, NCSC],
 faqs=[("Can a voice or video call hack me?","No. Calls on their own don’t give access to your account."),
  ("Can someone see my messages if they hack me?","Yes. Change your password and check Where you’re logged in."),
  ("What does “a code was sent to you by mistake” mean?","It’s a scam. That code lets them log in as you."),
  ("I clicked a link but didn’t log in. Am I safe?","Probably. Run a security check and change your password if unsure."),
  ("Can Unbanz help after a Messenger scam?","Yes, if Facebook’s own recovery fails. We use the official process."),
  ("How do I contact Unbanz?","Email team@unbanz.com with your profile link and a screenshot of the message.")],
 related=[("facebook-hacked-uk-what-to-do","Facebook hacked in the UK"),("uk/can-a-hacked-facebook-account-be-recovered","Can it be recovered?"),("facebook-hacked-ads-charged-to-my-card","Ads charged to your card"),("uk","All UK guides")],
))
